/* Persistence helper: uses Claude's window.storage when running inside an
   artifact preview, and falls back to localStorage for a normal deployed
   site (e.g. this project once it's running on its own). */
async function storageGet(key) {
  try {
    if (typeof window !== "undefined" && window.storage?.get) {
      const res = await window.storage.get(key, false);
      return res?.value ?? null;
    }
  } catch (e) {
    // fall through to localStorage
  }
  try {
    return typeof window !== "undefined" ? window.localStorage.getItem(key) : null;
  } catch (e) {
    return null;
  }
}

async function storageSet(key, value) {
  try {
    if (typeof window !== "undefined" && window.storage?.set) {
      await window.storage.set(key, value, false);
      return;
    }
  } catch (e) {
    // fall through to localStorage
  }
  try {
    if (typeof window !== "undefined") window.localStorage.setItem(key, value);
  } catch (e) {
    // ignore
  }
}

/* Deterministic-looking "random" order number generator, e.g. #47-456CL/NV */
function randomOrderNumber(stateAbbr) {
  const a = Math.floor(10 + Math.random() * 89);
  const b = Math.floor(100 + Math.random() * 899);
  return "#" + a + "-" + b + "CL/" + stateAbbr;
}

