function buildInitialOrders() {
  return EVENTS_CONFIG.map((evt) => ({
    ...evt,
    orderNumber: randomOrderNumber(evt.city.split(", ")[1] || "US"),
    tickets: Array.from({ length: evt.ticketCount }, (_, i) => ({
      id: evt.id + "-t" + (i + 1),
      label: "GA " + (i + 1),
      package: evt.package,
      type: evt.admission,
      section: evt.section,
      status: "ACTIVE",
    })),
  }));
}

