function StatusBadge({ status }) {
  const map = {
    ACTIVE: { text: "Active", cls: "text-green-600 bg-green-50" },
    TRANSFER_PENDING: { text: "Transfer Pending", cls: "text-blue-600 bg-blue-50" },
    TRANSFERRED: { text: "Transferred", cls: "text-gray-500 bg-gray-100" },
    USED: { text: "Used", cls: "text-gray-500 bg-gray-100" },
    CANCELLED: { text: "Cancelled", cls: "text-red-600 bg-red-50" },
  };
  const m = map[status] || map.ACTIVE;
  return <span className={"text-xs font-medium px-1.5 py-0.5 rounded " + m.cls}>{m.text}</span>;
}

