function LoginScreen({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(true);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = () => {
    setError("");
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      if (email.trim().toLowerCase() === DEMO_EMAIL && password === DEMO_PASSWORD) {
        onLogin(rememberMe);
      } else {
        setError("Incorrect email or password.");
      }
    }, 500);
  };

  return (
    <div className="min-h-full flex flex-col justify-center px-6 py-10">
      <div className="mb-8 text-center">
        <img src={LOGO_IMAGE} alt="Logo" className="w-14 h-14 rounded-2xl mx-auto mb-3 object-cover" />
        <h1 className="text-xl font-bold text-gray-900">Sign in</h1>
        <p className="text-sm text-gray-500 mt-1">Access your tickets and manage transfers</p>
      </div>

      <label className="text-xs font-medium text-gray-500 mb-1" htmlFor="email">
        Email
      </label>
      <input
        id="email"
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="Email"
        className="h-11 px-3 rounded border border-gray-300 text-sm mb-4 focus:outline-none focus:border-blue-600 focus:ring-1 focus:ring-blue-600"
      />

      <label className="text-xs font-medium text-gray-500 mb-1" htmlFor="password">
        Password
      </label>
      <input
        id="password"
        type="password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        placeholder="Password"
        className="h-11 px-3 rounded border border-gray-300 text-sm mb-2 focus:outline-none focus:border-blue-600 focus:ring-1 focus:ring-blue-600"
      />

      <button
        onClick={() => {
          setEmail(DEMO_EMAIL);
          setPassword(DEMO_PASSWORD);
        }}
        className="text-xs text-blue-600 text-left mb-4 self-start"
      >
        Forgot password?
      </button>

      {error && (
        <div className="flex items-center gap-2 text-sm text-red-600 mb-4">
          <AlertCircle size={16} />
          {error}
        </div>
      )}

      <PrimaryButton onClick={submit} loading={loading} disabled={!email || !password} pill>
        Sign In
      </PrimaryButton>

      <label className="mt-5 flex items-center justify-center gap-2 self-center select-none cursor-pointer">
        <input
          type="checkbox"
          checked={rememberMe}
          onChange={(e) => setRememberMe(e.target.checked)}
          className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-600"
        />
        <span className="text-xs text-gray-500">Remember me</span>
      </label>
    </div>
  );
}

