/* ------------------------------------------------------------------ */
/*  App shell / state machine                                          */
/* ------------------------------------------------------------------ */

export default function App() {
  const [loaded, setLoaded] = useState(false);
  const [authed, setAuthed] = useState(false);
  const [pendingAuth, setPendingAuth] = useState(false);
  const rememberChoice = useRef(false);
  const [orders, setOrders] = useState(() => buildInitialOrders());
  const [transfers, setTransfers] = useState([]);
  const [view, setView] = useState("myTickets");
  const [currentOrderId, setCurrentOrderId] = useState(null);
  const [selectedIds, setSelectedIds] = useState([]);
  const [recipient, setRecipient] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const value = await storageGet(STORAGE_KEY);
        if (value) {
          const parsed = JSON.parse(value);
          if (parsed.orders) setOrders(parsed.orders);
          if (parsed.transfers) setTransfers(parsed.transfers);
        }
        const remembered = await storageGet(REMEMBER_KEY);
        if (remembered === "1") {
          setAuthed(true);
        }
      } catch (e) {
        // no saved state yet
      } finally {
        setLoaded(true);
      }
    })();
  }, []);

  useEffect(() => {
    if (!loaded) return;
    storageSet(STORAGE_KEY, JSON.stringify({ orders, transfers }));
  }, [orders, transfers, loaded]);

  const currentOrder = orders.find((o) => o.id === currentOrderId) || null;

  const startTransfer = (ticketId) => {
    setSelectedIds(ticketId ? [ticketId] : []);
    setView("transferAuthLoading");
    setTimeout(() => setView("transferAuth"), 900);
  };

  const cancelTransfer = () => {
    setSelectedIds([]);
    setRecipient(null);
    setView("order");
  };

  const completeTransfer = (recipientInfo) => {
    setView("processing");
    setTimeout(() => {
      setOrders((prev) =>
        prev.map((o) =>
          o.id !== currentOrderId
            ? o
            : {
                ...o,
                tickets: o.tickets.map((t) =>
                  selectedIds.includes(t.id)
                    ? { ...t, status: "TRANSFERRED", recipientName: recipientInfo.firstName + " " + recipientInfo.lastName }
                    : t
                ),
              }
        )
      );
      setTransfers((prev) => [
        {
          id: "tr-" + Date.now(),
          recipientName: recipientInfo.firstName + " " + recipientInfo.lastName,
          eventName: currentOrder ? currentOrder.name : "",
          ticketCount: selectedIds.length,
          date: new Date().toISOString(),
        },
        ...prev,
      ]);
      setView("success");
    }, 900);
  };

  if (!loaded) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 size={24} className="animate-spin text-blue-600" />
      </div>
    );
  }

  let screen = null;
  if (!authed) {
    screen = pendingAuth ? (
      <OtpScreen
        recipient={{ method: "email", email: DEMO_EMAIL }}
        onBack={() => setPendingAuth(false)}
        onCancel={() => setPendingAuth(false)}
        onVerified={() => {
          setPendingAuth(false);
          setAuthed(true);
          setView("myTickets");
          if (rememberChoice.current) {
            storageSet(REMEMBER_KEY, "1");
          }
        }}
      />
    ) : (
      <LoginScreen
        onLogin={(remembered) => {
          rememberChoice.current = remembered;
          setPendingAuth(true);
        }}
      />
    );
  } else if (view === "myTickets") {
    screen = (
      <MyTicketsScreen
        orders={orders}
        onOpenOrder={(id) => {
          setCurrentOrderId(id);
          setView("order");
        }}
        onLogout={() => {
          setAuthed(false);
          setView("myTickets");
          storageSet(REMEMBER_KEY, "");
        }}
      />
    );
  } else if (view === "order" && currentOrder) {
    screen = (
      <OrderDetailScreen
        order={currentOrder}
        onBack={() => setView("myTickets")}
        onTransfer={startTransfer}
        onViewHistory={() => setView("history")}
      />
    );
  } else if (view === "transferAuthLoading" && currentOrder) {
    screen = <TransferAuthLoading order={currentOrder} />;
  } else if (view === "transferAuth") {
    screen = (
      <OtpScreen
        recipient={{ method: "email", email: DEMO_EMAIL }}
        onBack={() => setView("order")}
        onCancel={cancelTransfer}
        onVerified={() => setView("transferSelect")}
      />
    );
  } else if (view === "transferSelect" && currentOrder) {
    screen = (
      <TransferSelectScreen
        order={currentOrder}
        preselected={selectedIds[0]}
        onBack={() => setView("order")}
        onCancel={cancelTransfer}
        onContinue={(ids) => {
          setSelectedIds(ids);
          setView("transferMethod");
        }}
      />
    );
  } else if (view === "transferMethod") {
    screen = <TransferMethodScreen onBack={() => setView("transferSelect")} onCancel={cancelTransfer} onManual={() => setView("recipientForm")} />;
  } else if (view === "recipientForm") {
    screen = (
      <RecipientForm
        onBack={() => setView("transferMethod")}
        onCancel={cancelTransfer}
        onSubmit={(info) => {
          setRecipient(info);
          setView("otp");
        }}
      />
    );
  } else if (view === "otp") {
    screen = <OtpScreen recipient={recipient} onBack={() => setView("recipientForm")} onCancel={cancelTransfer} onVerified={() => completeTransfer(recipient)} />;
  } else if (view === "processing") {
    screen = <ProcessingScreen />;
  } else if (view === "success" && currentOrder) {
    screen = (
      <SuccessScreen
        order={currentOrder}
        count={selectedIds.length}
        recipient={recipient}
        onDone={() => {
          setSelectedIds([]);
          setRecipient(null);
          setView("myTickets");
        }}
      />
    );
  } else if (view === "history") {
    screen = <HistoryScreen transfers={transfers} onBack={() => setView("order")} />;
  } else {
    screen = <MyTicketsScreen orders={orders} onOpenOrder={(id) => { setCurrentOrderId(id); setView("order"); }} onLogout={() => { setAuthed(false); storageSet(REMEMBER_KEY, ""); }} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex justify-center font-sans">
      <div className="w-full bg-white shadow-sm flex flex-col" style={{ maxWidth: "480px" }}>
        {screen}
      </div>
    </div>
  );
}
